    bg_val = max(counts.items(), key=lambda x: x[1])[0] if counts else 0

    # Create output grid filled with background
    out = [[bg_val for _ in range(len(grid[0]))] for _ in range(H)]

    # Keep separator row unchanged
    out[sep_r] = grid[sep_r][:]

